import{_ as n,c as l,h as a,b as i,i as t,e as o,w as r,j as p,a as c}from"./app-DuwZQ5pu.js";const d="/assets/img/MachineLearning/Voyager2.jpg",m={};function h(g,e){const s=p("font");return c(),l("div",null,[e[3]||(e[3]=a('<img src="'+d+'" style="display:block;margin:0 auto;"><link rel="stylesheet" href="/css/font-style.css"><h2 id="小梦" tabindex="-1"><a class="header-anchor" href="#小梦"><span>小梦</span></a></h2><p> 好久没写博客了，这中间发生了一些事，有点烦躁所以想起来可以写博客。</p><h2 id="现实与理想" tabindex="-1"><a class="header-anchor" href="#现实与理想"><span>现实与理想</span></a></h2><p> 关于理想，我想不需要表达太多。如果是熟悉我的人，他们可能会认为我是一个理想主义者（指正，是在悲观主义下的理想主义者）。过多的要求和做过多的妥协，一方面是尽可能的改变自己、改变环境，另一方面是察觉实现的困难和复杂而选择摆烂。不过我对自己也蛮狠的，虽然更多的是在麻痹自我，希望使用更多的任务来让自己感到充实...我更想做一个佛系的人，不争不抢，有自己喜欢的东西就好。</p>',6)),i("p",null,[e[1]||(e[1]=t(" 但是嫉妒、自卑、贪欲是一个正常人应该有的情绪，我不要求别人为我做什么，我只希望尽我所能奋力挣扎一下，去为了满足仅有的一些“凡人的需要”？或许吧，就像我曾经说过的")),o(s,{class:"gradient-title"},{default:r(()=>e[0]||(e[0]=[t("“人就是这样，当出现情绪的时候，道德和品行永远置于理性之后，这点无关乎学历高低。那些表面光鲜亮丽的人背后一定藏着偷鸡摸狗的勾当，问题在于能否有人能跳出来指出并大胆承认……如果有，那我十分愿意当第一个（接受自己的不堪也同样重要）。”")])),_:1,__:[0]}),e[2]||(e[2]=t("所以我才在不断地在否定自己和肯定自己中循环。我否定的是以往在他人/我看来不符合道德的我做的事，但是我又积极肯定我曾经走过的路。一方面是败坏的、另一方面是积极的。而现在看来，并没有什么对和错，这均是在大众里，不同人对这件事/人分门别类地看法...所以我也可以理解加缪和他曾经决裂过的好友所谈及的类似“及时行乐”的事，但我无法认同（比如更加偏激的唐璜）。而我更像是我读的书《罪与罚》中的索尼娅，那种被逼无奈踏上一条路，但又不得不背负一些什么前行的人（除了她所涉及的宗教主义）。且她要比我更加艰难..."))]),e[4]||(e[4]=a('<p> 所以他们这一类人不知道现实么？他们知道的...只不过做法不同......有人选择快乐的活着，而有人却选择承认罪孽并接受它，这并没有什么对错。这里我应该更正之前在动态里发过的关于强化学习下的学习论法：没有什么是绝对的，我所提到的“他们甚至没有意识到自己要干什么？”这句话本身就带有很强的蔑视和高傲。毫无疑问，这一次悉达多“胜出了”，因为当时佛陀也是这么做的...佛陀和悉达多的对话就表示了“这种非绝对性和真理无法言说，你只能通过内心去理解感悟”，即便佛陀在传授他的说教给众人，可唯独悉达多，唯独悉达多点明了真正的道理，这也是他和他的友人分别的一个原因（当然，这也对错难分，苦笑）。</p><p> 理想是极具戏剧色彩的，我们无法想象在理想的驱动下一个人能做到什么程度。但是，弗洛伦萨在 14 世纪下的余晖依旧会在本世纪闪耀，黑暗时期的人们和那些来自北方地区的“蛮夷”也不会明白后世的人究竟该怎么来表达那些神话故事，撑起历史画布中的那些参与者更不会清晰知道我们会怎么思考他们，我们也不会去矢口否定这些前人的智慧和道理，这毫无价值可言。倒不如做一个旁观者、一个深思熟虑但毫无评价的旁观者（就像在河边看平静的河一样，表情毫无波澜，但内心激荡）。</p><h2 id="具有批判性色彩的" tabindex="-1"><a class="header-anchor" href="#具有批判性色彩的"><span>具有批判性色彩的</span></a></h2><p> 我最近和弗洛伊德一直在“纠缠”，不知道怎么的这家伙阴魂不散。这家伙言辞十分犀利，甚至毫不留情。能把别人的内心阴暗面/隐私面揭露的毫不保留。我不知道怎么评价他，但是毫无疑问他是我阅读经典留下浓墨重彩的一个人。为什么要提他？因为我需要他的理论帮我分析我自己和周围的所有人（观察一个人很有意思，但是我不会说出来，因为说出来那就和弗洛伊德本人没区别了，参考他的人员关系）。比如《罪与罚》的男主人公（下文简称男主）和与他相对应的九品文官（下文简称九）。托翁的手法及其精妙，以第三人称视角对人物角色进行侵入式的性格刨析，甚至心理、动作和表情特征。毫无疑问这应该是我读过的小说里出色的了（废话），所以我们可以直接用老佛爷的理论对他们进行操刀。</p><p> 首先是对于男主杀人前所遇到的巧合的描写，所有的巧合在老佛爷理论里均为心理暗示，除此以外还有失误、做梦等，所以男主在后来的杀人中才会显得那么理所应当，认为是上天安排；关于九，我认为一是作为暗示存在，他会因为他所犯下的罪孽而付出代价，二是和男主的命运相互关联。关于九，我想说的是他内心的扭曲和矛盾，因为索尼娅（他的女儿）的原因而变得自责，但是自责又无能为力，弃官卖衣抵债酗酒，所做的一切都是他自以为是的对自己罪孽的抵偿，是本我与超我的割裂（无法作为，只能酗酒）；同样的，关于男主的性格也同样如此，他认为人就应该三六九等（他的论文），甚至幻想过自己是改变世界的那个人（拿破仑），但现实是抛弃好友递来的橄榄枝，拿自己的东西进行抵债买酒。他的&quot;超人理论&quot;是一种防御机制——合理化（Rationalization）。他将谋杀包装成哲学命题，实则是掩盖弑父冲动（放高利贷的老太婆象征权威与压迫性的形象）。疾病与谵妄是躯体化的罪恶感，而最终的自首与皈依，代表超我重新整合人格，爱索尼娅成为他重建自我（Ego）的锚点。</p><p> 反过来，各位或许会问：这真的有道理么！还是胡编乱造？我不知道，但是我知道我可以保持沉默，就像我现在应该提醒读者，心理学的终点是回归自己，你想怎么样做就怎么样做！你应该听从什么大名鼎鼎的理论基础和实践教程么？或许应该想想再做出回答！同样的，我曾说过读书仅是为了消遣时间，看看过去或者现在的人们怎么看待/评价一个人/事/物。真的有对错么？或许我该问...你或许需要丢掉书到喷泉中去！</p><h2 id="小梦醒时" tabindex="-1"><a class="header-anchor" href="#小梦醒时"><span>小梦醒时</span></a></h2><p> 梦醒时分初见一阵石榴红，那会是什么？是真知灼见还是稀里糊涂？你该去下床看看的...</p>',8))])}const u=n(m,[["render",h]]),k=JSON.parse('{"path":"/posts/littleDream.html","title":"小梦","lang":"en-US","frontmatter":{"title":"小梦","description":"小梦","date":"2026-03-18T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"小梦"}],["meta",{"name":"description","content":"小梦"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["碎碎念"]},"headers":[{"level":2,"title":"小梦","slug":"小梦","link":"#小梦","children":[]},{"level":2,"title":"现实与理想","slug":"现实与理想","link":"#现实与理想","children":[]},{"level":2,"title":"具有批判性色彩的","slug":"具有批判性色彩的","link":"#具有批判性色彩的","children":[]},{"level":2,"title":"小梦醒时","slug":"小梦醒时","link":"#小梦醒时","children":[]}],"git":{"updatedTime":1773851680000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":2}],"changelog":[{"hash":"756fd7fd120f5950e0ac9182889d560eda6112e9","time":1773851680000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"new file"},{"hash":"ce64ca1904084ff9d50014a18c3e955a2d881e69","time":1773850382000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"new file"}]},"filePathRelative":"posts/littleDream.md","excerpt":"<img src=\\"/assets/img/MachineLearning/Voyager2.jpg\\" style=\\"display: block;margin: 0 auto;\\">\\n<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<h2>小梦</h2>\\n<p> 好久没写博客了，这中间发生了一些事，有点烦躁所以想起来可以写博客。</p>\\n<h2>现实与理想</h2>\\n<p> 关于理想，我想不需要表达太多。如果是熟悉我的人，他们可能会认为我是一个理想主义者（指正，是在悲观主义下的理想主义者）。过多的要求和做过多的妥协，一方面是尽可能的改变自己、改变环境，另一方面是察觉实现的困难和复杂而选择摆烂。不过我对自己也蛮狠的，虽然更多的是在麻痹自我，希望使用更多的任务来让自己感到充实...我更想做一个佛系的人，不争不抢，有自己喜欢的东西就好。</p>"}');export{u as comp,k as data};
